-- File: 01-list-pending.sql
-- Purpose: 列出所有 pending 食安檢舉，依 SLA 急迫度排序（食安檢舉 severity 恆為 critical）
-- When to use: admin UI 故障 / 部署中無法連線時，admin 用 psql 直連 seller-service Postgres 取得待處理清單
-- Variables to fill: 無（純查詢，可直接執行）
-- Audit: 執行後將完整 SQL + 結果貼到 Discord #food-safety-actions channel 留紀錄
-- Generated by B-169 (issue #722) — 2026-05-07

-- food_safety_reports 食安檢舉皆視為 critical（4 小時 SLA acknowledge）
-- 排序邏輯：
--   1. acknowledged_at IS NULL 排前面（尚未 ack 的最緊急）
--   2. 然後依 created_at ASC（越早收到越急）
SELECT
    id,
    target_seller_id,
    target_product_id,
    target_order_no,
    reporter_phone,
    reporter_name,
    LEFT(description, 80) AS description_preview,
    status,
    acknowledged_at,
    acknowledged_by_admin_id,
    investigating_at,
    fda_reported_at,
    created_at,
    -- SLA 計時：自 created_at 起算，4 小時內必須 ack
    CASE
        WHEN acknowledged_at IS NOT NULL THEN 'acknowledged'
        WHEN now() - created_at > interval '4 hours' THEN 'SLA_BREACHED'
        WHEN now() - created_at > interval '3 hours' THEN 'SLA_WARNING'
        ELSE 'on_track'
    END AS sla_status,
    EXTRACT(EPOCH FROM (now() - created_at)) / 60 AS minutes_since_reported
FROM food_safety_reports
WHERE status = 'pending'
ORDER BY
    (acknowledged_at IS NULL) DESC,  -- 未 ack 的排前
    created_at ASC                   -- 越早收到越前面
;

-- 額外輔助查詢：統計待處理數量與 SLA 狀態
SELECT
    COUNT(*) FILTER (WHERE acknowledged_at IS NULL) AS pending_unack,
    COUNT(*) FILTER (WHERE acknowledged_at IS NULL AND now() - created_at > interval '4 hours') AS sla_breached,
    COUNT(*) FILTER (WHERE acknowledged_at IS NULL AND now() - created_at > interval '3 hours' AND now() - created_at <= interval '4 hours') AS sla_warning,
    COUNT(*) AS total_pending
FROM food_safety_reports
WHERE status = 'pending'
;
